local Junkie = loadstring(game:HttpGet("https://jnkie.com/sdk/library.lua"))()
Junkie.service = "westbound-service-linkvertise"
Junkie.identifier = "1007877"
Junkie.provider = "westbound-provider-linkvertise"

local SCRIPT_KEY = nil
local KEY_EXPIRY_TIME = nil
local GETKEY_COOLDOWN_END = nil

local function SavePersistentData()
    if writefile then
        local data = {
            key = SCRIPT_KEY,
            expiry = KEY_EXPIRY_TIME,
            cooldown = GETKEY_COOLDOWN_END
        }
        writefile("veneno_hub_data.json", game:GetService("HttpService"):JSONEncode(data))
    end
end

local function LoadPersistentData()
    if readfile and isfile and isfile("veneno_hub_data.json") then
        local success, data = pcall(function()
            return game:GetService("HttpService"):JSONDecode(readfile("veneno_hub_data.json"))
        end)
        if success and data then
            SCRIPT_KEY = data.key
            KEY_EXPIRY_TIME = data.expiry
            GETKEY_COOLDOWN_END = data.cooldown
            
            if KEY_EXPIRY_TIME and os.time() > KEY_EXPIRY_TIME then
                SCRIPT_KEY = nil
                KEY_EXPIRY_TIME = nil
                SavePersistentData()
            end
            
            if GETKEY_COOLDOWN_END and os.time() > GETKEY_COOLDOWN_END then
                GETKEY_COOLDOWN_END = nil
                SavePersistentData()
            end
        end
    end
end

local function VerifyWithJunkie()
    getgenv().UI_CLOSED = false
    
    local Players = game:GetService("Players")
    local TweenService = game:GetService("TweenService")
    local UserInputService = game:GetService("UserInputService")
    local Lighting = game:GetService("Lighting")
    
    LoadPersistentData()
    
    if SCRIPT_KEY then
        local result = nil
        
        local success, err = pcall(function()
            result = Junkie.check_key(SCRIPT_KEY)
        end)
        
        if success and result and result.valid then
            KEY_EXPIRY_TIME = os.time() + (24 * 60 * 60)
            SavePersistentData()
            getgenv().UI_CLOSED = true
            return SCRIPT_KEY
        else
            SCRIPT_KEY = nil
            KEY_EXPIRY_TIME = nil
            SavePersistentData()
        end
    end
    
    if KEY_EXPIRY_TIME and os.time() > KEY_EXPIRY_TIME then
        SCRIPT_KEY = nil
        KEY_EXPIRY_TIME = nil
        SavePersistentData()
    end
    
