        verifyBtn.Size = UDim2.new(0.48, 0, 1, 0)
        verifyBtn.Position = UDim2.new(0.52, 0, 0, 0)
        verifyBtn.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
        verifyBtn.Text = "VERIFY KEY"
        verifyBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
        verifyBtn.Font = Enum.Font.SourceSansBold
        verifyBtn.TextSize = isMobile and 12 or 14
        verifyBtn.Parent = buttonSection
        
        local verifyCorner = Instance.new("UICorner")
        verifyCorner.CornerRadius = UDim.new(0, 6)
        verifyCorner.Parent = verifyBtn
        
        local statusLabel = Instance.new("TextLabel")
        statusLabel.Size = UDim2.new(1, 0, 0, 25)
        statusLabel.BackgroundTransparency = 1
        statusLabel.Text = "STATUS: WAITING FOR KEY"
        statusLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
        statusLabel.Font = Enum.Font.SourceSansBold
        statusLabel.TextSize = isMobile and 12 or 14
        statusLabel.Parent = content
        
        if isMobile then
            layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
                container.Size = UDim2.new(0.85, 0, 0, layout.AbsoluteContentSize.Y + 100)
