            closeBtn = closeBtn,
            isMobile = isMobile
        }
        
        local function setupButton(btn, defaultColor, hoverColor)
            btn.MouseEnter:Connect(function()
                btn.BackgroundColor3 = hoverColor
            end)
            btn.MouseLeave:Connect(function()
                btn.BackgroundColor3 = defaultColor
            end)
        end
        
